// Single-digit Gujarati + Devanagari word map (for phone numbers)
const singleDigitMap = {
    'શૂન્ય': '0', 'ઝીરો': '0', '૦': '0', 'शून्य': '0', 'जीरो': '0', '०': '0',
    'એક': '1', '૧': '1', 'वन': '1', 'एक': '1', '१': '1',
    'બે': '2', '૨': '2', 'ટુ': '2', 'ટૂ': '2', 'दो': '2', 'बे': '2', '२': '2',
    'ત્રણ': '3', '૩': '3', 'થ્રી': '3', 'तीन': '3', 'त्रण': '3', '३': '3',
    'ચાર': '4', '૪': '4', 'ફોર': '4', 'चार': '4', '४': '4',
    'પાંચ': '5', '૫': '5', 'ફાઇવ': '5', 'ફાઈવ': '5', 'पांच': '5', 'पाँच': '5', '५': '5',
    'છ': '6', '૬': '6', 'સિક્સ': '6', 'छह': '6', 'छे': '6', '६': '6',
    'સાત': '7', '૭': '7', 'સેવન': '7', 'सात': '7', '७': '7',
    'આઠ': '8', '૮': '8', 'એટ': '8', 'आठ': '8', 'आट': '8', '८': '8',
    'નવ': '9', '૯': '9', 'નાઇન': '9', 'નાઈન': '9', 'नौ': '9', 'नव': '9', '९': '9'
};

const compoundMap = {
    'અગિયાર': '11', 'ग्यारह': '11', 'બાર': '12', 'बारह': '12',
    'તેર': '13', 'तेरह': '13', 'ચૌદ': '14', 'चौदह': '14',
    'પંદર': '15', 'पंद्रह': '15', 'સોળ': '16', 'सोलह': '16',
    'સત્તર': '17', 'सत्रह': '17', 'અઢાર': '18', 'अठारह': '18',
    'ઓગણીસ': '19', 'उन्नीस': '19', 'વીસ': '20', 'बीस': '20',
    'એકવીસ': '21', 'इक्कीस': '21', 'બાવીસ': '22', 'बाईस': '22',
    'ત્રેવીસ': '23', 'तेईस': '23', 'ચોવીસ': '24', 'चौबीस': '24',
    'પચ્ચીસ': '25', 'पच्चीस': '25', 'છવ્વીસ': '26', 'छब्बीस': '26',
    'સત્તાવીસ': '27', 'सत्ताईस': '27', 'અઠ્ઠાવીસ': '28', 'अट्ठाईस': '28',
    'ઓગણત્રીસ': '29', 'उनतीस': '29', 'ત્રીસ': '30', 'तीस': '30',
    'એકત્રીસ': '31', 'इकतीस': '31', 'દસ': '10', 'दस': '10'
};

for (const item of $input.all()) {
    const query = $('Webhook').first().json.query || {};
    const webhookHistory = ($('Webhook').first().json.history || '').trim();

    if (query.start_date && query.end_date) {
        // Server pre-parsed dates — use directly, skip STT normalization
        item.json.input = `check-in: ${query.start_date}, check-out: ${query.end_date}`;
    } else {
        // Normalize STT transcript
        let text = item.json.text || item.json.transcript || '';
        let normalized = text;
        for (const [word, digit] of Object.entries(compoundMap)) {
            normalized = normalized.split(word).join(digit);
        }
        normalized = normalized.toLowerCase();
        for (const [word, digit] of Object.entries(singleDigitMap)) {
            normalized = normalized.split(word).join(digit);
        }
        normalized = normalized.replace(/\b(\d)\b\s+(?=\b\d\b)/g, '$1');
        item.json.input = normalized;
    }

    item.json.transcript = item.json.input;

    // Always inject GREETING_DONE on first turn for verified users
    // so the AI Agent skips get_identity and goes straight to the booking questions
    if (query.verified === 'true' && query.name && !webhookHistory) {
        item.json.input = `[GREETING_DONE:name=${query.name},centre=${query.centre_name}] ${item.json.input}`;
    }
}
return $input.all();
